          "type": "HTTP cookie",
          "purpose": "Stores your cookie consent choices for this website.",
          "duration": "1 year",
          "infoHref": "https://www.cookiebot.com/en/privacy-policy/"
        },
        {
          "name": "__cf_bm",
          "provider": "HubSpot (via Cloudflare)",
          "type": "HTTP cookie",
          "purpose": "Tells humans and bots apart, to protect HubSpot’s services from malicious traffic.",
          "duration": "30 minutes",
          "infoHref": "https://legal.hubspot.com/privacy-policy"
        },
        {
          "name": "test_cookie",
          "provider": "Google (doubleclick.net)",
          "type": "HTTP cookie",
          "purpose": "Checks whether your browser supports cookies.",
          "duration": "15 minutes",
          "infoHref": "https://business.safety.google/privacy/"
        },
        {
          "name": "sveltekit:scroll, sveltekit:snapshot",
          "provider": "Privacy Culture",
          "type": "HTML session storage",
          "purpose": "Remembers your place on a page so the back button returns you to where you were.",
          "duration": "Session",
          "infoHref": "/privacy-policy"
        }
      ]
    },
    {
      "id": "statistics",
      "title": "Statistics",
      "cookies": [
        {
          "name": "_ga",
          "provider": "Google Analytics",
          "type": "HTTP cookie",
          "purpose": "Registers a unique ID used to produce statistics on how you use the website.",
          "duration": "2 years",
          "infoHref": "https://business.safety.google/privacy/"
        },
        {
          "name": "_ga_M67X8M2TQR",
          "provider": "Google Analytics",
          "type": "HTTP cookie",
          "purpose": "Keeps track of your session, including how many times you have visited and the dates of your first and most recent visit.",
          "duration": "2 years",
          "infoHref": "https://business.safety.google/privacy/"
        },
        {
          "name": "_hjSessionUser_6785893",
          "provider": "Hotjar",
          "type": "HTTP cookie",
          "purpose": "Gives you a unique ID the first time you visit, so your later visits are recognised as the same visitor.",
          "duration": "1 year",
          "infoHref": "https://www.hotjar.com/legal/policies/privacy/"
        },
        {
          "name": "_hjSession_6785893",
          "provider": "Hotjar",
          "type": "HTTP cookie",
          "purpose": "Holds data for the current session, so page views in the same visit are grouped together.",
          "duration": "30 minutes",
          "infoHref": "https://www.hotjar.com/legal/policies/privacy/"
        },
        {
          "name": "__hstc",
          "provider": "HubSpot",
          "type": "HTTP cookie",
          "purpose": "Tracks visitors, storing the time of your first visit, your previous visit and your current one, and how many sessions you have had.",
          "duration": "6 months",
          "infoHref": "https://legal.hubspot.com/privacy-policy"
        },
        {
          "name": "hubspotutk",
          "provider": "HubSpot",
          "type": "HTTP cookie",
          "purpose": "Keeps track of your identity as a visitor, so HubSpot can recognise you across sessions and produce visitor statistics.",
          "duration": "6 months",
          "infoHref": "https://legal.hubspot.com/privacy-policy"
        },
        {
          "name": "__hssc",
          "provider": "HubSpot",
          "type": "HTTP cookie",
          "purpose": "Counts page views in a session and works out whether the session count needs updating.",
          "duration": "30 minutes",
          "infoHref": "https://legal.hubspot.com/privacy-policy"
        },
        {
          "name": "__hssrc",
          "provider": "HubSpot",
          "type": "HTTP cookie",
          "purpose": "Recognises when you have restarted your browser, to tell new sessions apart.",
          "duration": "Session",
          "infoHref": "https://legal.hubspot.com/privacy-policy"
        },
        {
          "name": "pc_demo_utm",
          "provider": "Privacy Culture",
          "type": "HTML session storage",
          "purpose": "Remembers the campaign link (UTM tags) that brought you to the site, so that if you book a demo we know which campaign it came from.",
          "duration": "Session",
          "infoHref": "/privacy-policy"
        }
      ]
    },
    {
      "id": "marketing",
      "title": "Marketing",
      "cookies": [
        {
          "name": "_gcl_au",
          "provider": "Google Ads",
          "type": "HTTP cookie",
          "purpose": "Stores click information from our ads so that demo bookings can be linked back to the ad that led to them.",
          "duration": "3 months",
          "infoHref": "https://business.safety.google/privacy/"
        },
        {
          "name": "_gcl_ls",
          "provider": "Google Ads",
          "type": "HTML local storage",
          "purpose": "A copy of the ad click information in _gcl_au, used when cookies are not available.",
          "duration": "Persistent",
          "infoHref": "https://business.safety.google/privacy/"
        },
        {
          "name": "IDE",
          "provider": "Google (doubleclick.net)",
          "type": "HTTP cookie",
          "purpose": "Records your actions after viewing or clicking one of our ads, to measure how well the ad works and show you more relevant ads.",
          "duration": "13 months",
          "infoHref": "https://business.safety.google/privacy/"
        },
        {
          "name": "pagead/1p-user-list/#, rmkt/collect/#",
          "provider": "Google Ads",
          "type": "Pixel tracker",
          "purpose": "Adds visitors to our remarketing audiences and records conversions, so we can show relevant ads on other websites and limit how often you see the same one.",
          "duration": "Session",
          "infoHref": "https://business.safety.google/privacy/"
        },
        {
          "name": "__ptq.gif",
          "provider": "HubSpot",
          "type": "Pixel tracker",
          "purpose": "Sends information about your device and behaviour to HubSpot, our marketing platform, and tracks you across devices and marketing channels.",
          "duration": "Session",
          "infoHref": "https://legal.hubspot.com/privacy-policy"
        }
      ]
    }
  ],
  "consentButtonLabel": "Change your cookie settings"
